//! Test that C++ overloads for [std::unordered_multiset][unordered_multiset] can be successfully represented in Rust.
//!
//! [unordered_multiset]: https://en.cppreference.com/cpp/container/unordered_multiset

#![allow(unused_braces, reason = "Generated by overload! macro")]

use cpp::cpp;
use splat_overload::overload;
use std::ffi::{c_char, c_size_t, c_void};
use std::marker::PhantomData;

// C++ header includes
cpp! {{
    #include <unordered_set>
    #include <vector>
    #include <cstddef>
}}

/// A wrapper struct to hold the returned C++ `std::unordered_multiset<int>` pointer.
///
/// ### Limitations
///
/// This struct and the impl should be fully generic over the set type.
/// FIXME: make the `overload!` macro support generics.
#[cfg_attr(not(test), expect(dead_code, reason = "Only used in tests"))]
pub struct StdUnorderedMultiset(*mut c_void, PhantomData<T>);

/// Workaround for missing generic support in the `overload!` macro.
pub type T = std::ffi::c_int;

/// Tag type to call constructor with default hash function.
#[derive(Clone, Copy)]
pub struct DefaultHash;

/// Tag type to call constructor with default key equality function.
#[derive(Clone, Copy)]
pub struct DefaultKeyEqual;

#[cfg_attr(not(test), expect(dead_code, reason = "Only used in tests"))]
#[allow(
    non_upper_case_globals,
    reason = "Triggered by cpp! macro in rust-analyzer"
)]
impl StdUnorderedMultiset {
    fn default() -> StdUnorderedMultiset {
        let set = unsafe {
            cpp!([] -> *mut c_void as "std::unordered_multiset<int>*" {
                return new std::unordered_multiset<int>();
            })
        };
        StdUnorderedMultiset(set, PhantomData)
    }

    fn from_bucket_count(bucket_count: c_size_t) -> StdUnorderedMultiset {
        let set = unsafe {
            cpp!([bucket_count as "size_t"] -> *mut c_void as "std::unordered_multiset<int>*" {
                return new std::unordered_multiset<int>(bucket_count);
            })
        };
        StdUnorderedMultiset(set, PhantomData)
    }

    fn copy_from(other: &StdUnorderedMultiset) -> StdUnorderedMultiset {
        let other_ptr = other.0 as *const c_void;
        let set = unsafe {
            cpp!([other_ptr as "const std::unordered_multiset<int>*"] -> *mut c_void as "std::unordered_multiset<int>*" {
                return new std::unordered_multiset<int>(*other_ptr);
            })
        };
        StdUnorderedMultiset(set, PhantomData)
    }

    fn from_slice(items: &[T]) -> StdUnorderedMultiset {
        let len = items.len();
        let items: *const T = items.as_ptr();
        let set = unsafe {
            cpp!([items as "const int*", len as "size_t"] -> *mut c_void as "std::unordered_multiset<int>*" {
                return new std::unordered_multiset<int>(items, items + len);
            })
        };
        StdUnorderedMultiset(set, PhantomData)
    }

    fn from_initializer_list_2(a: T, b: T) -> StdUnorderedMultiset {
        let set = unsafe {
            cpp!([a as "int", b as "int"] -> *mut c_void as "std::unordered_multiset<int>*" {
                return new std::unordered_multiset<int>{ a, b };
            })
        };
        StdUnorderedMultiset(set, PhantomData)
    }

    fn from_hash(_tag: DefaultHash) -> StdUnorderedMultiset {
        let set = unsafe {
            cpp!([] -> *mut c_void as "std::unordered_multiset<int>*" {
                return new std::unordered_multiset<int>(0, std::hash<int>());
            })
        };
        StdUnorderedMultiset(set, PhantomData)
    }

    fn from_key_equal(_tag: DefaultKeyEqual) -> StdUnorderedMultiset {
        let set = unsafe {
            cpp!([] -> *mut c_void as "std::unordered_multiset<int>*" {
                return new std::unordered_multiset<int>(0, std::hash<int>(), std::equal_to<int>());
            })
        };
        StdUnorderedMultiset(set, PhantomData)
    }

    fn insert_value(&mut self, value: T) {
        let slf: *mut c_void = self.0;
        unsafe {
            cpp!([slf as "std::unordered_multiset<int>*", value as "int"] {
                slf->insert(value);
            })
        }
    }

    fn insert_range(&mut self, items: &[T]) {
        let slf: *mut c_void = self.0;
        let len = items.len();
        let items: *const T = items.as_ptr();
        unsafe {
            cpp!([slf as "std::unordered_multiset<int>*", items as "const int*", len as "size_t"] {
                slf->insert(items, items + len);
            })
        }
    }

    fn count(&self, value: T) -> c_size_t {
        let slf = self.0 as *const c_void;
        unsafe {
            cpp!([slf as "const std::unordered_multiset<int>*", value as "int"] -> c_size_t as "size_t" {
                return slf->count(value);
            })
        }
    }

    fn is_empty(&self) -> bool {
        let slf = self.0 as *const c_void;
        let empty = unsafe {
            cpp!([slf as "const std::unordered_multiset<int>*"] -> c_char as "char" {
                return slf->empty();
            })
        };
        empty != 0
    }
}

overload! {
    impl StdUnorderedMultiset {
        /// Construct an empty set.
        ///
        /// ### Limitations
        ///
        /// The `overload!` macro does not support generics, so the implementation is hardcoded to `int` type.
        /// Rust doesn't have default function arguments like C++ does. In C++, you can call
        /// `unordered_multiset(size_type, const Hash& = Hash(), const key_equal& = key_equal())`
        /// with 1, 2, or 3 arguments. In Rust, we'd need a separate overload for each combination.
        /// For this one constructor, that would mean overloads for:
        /// - (bucket_count)
        /// - (bucket_count, hash)
        /// - (bucket_count, hash, key_equal)
        /// - (bucket_count, hash, key_equal, allocator)
        /// This gets out of hand quickly when you have multiple constructors with default arguments.
        /// Also, the `cpp!` macro can't be used inside the `overload!` macro, so we can't easily
        /// call constructors that need C++ function objects like `std::hash<int>()`.
        pub fn new() -> StdUnorderedMultiset {
            StdUnorderedMultiset::default()
        }

        /// Construct a set with at least `bucket_count` buckets.
        pub fn new(bucket_count: c_size_t) -> StdUnorderedMultiset {
            StdUnorderedMultiset::from_bucket_count(bucket_count)
        }

        /// Construct a set by copying from another set.
        pub fn new(other: &StdUnorderedMultiset) -> StdUnorderedMultiset {
            StdUnorderedMultiset::copy_from(other)
        }

        /// Construct a set by copying items from a slice.
        ///
        /// ### Ergonomics
        ///
        /// The `as_slice()` call is required to match the slice overload, as arrays don't automatically coerce.
        pub fn new(items: &[T]) -> StdUnorderedMultiset {
            StdUnorderedMultiset::from_slice(items)
        }

        /// Construct a set from an initializer list.
        ///
        /// ### Ergonomics
        ///
        /// Initializer list overloads require separate functions for each argument count, which is not ergonomic.
        pub fn new(a: T, b: T) -> StdUnorderedMultiset {
            StdUnorderedMultiset::from_initializer_list_2(a, b)
        }

        /// Construct a set with a default hash function.
        ///
        /// This demonstrates calling a C++ constructor with default arguments.
        /// In C++, this would be `unordered_multiset(0, std::hash<int>())` where
        /// the remaining arguments use their default values.
        pub fn new(_tag: DefaultHash) -> StdUnorderedMultiset {
            StdUnorderedMultiset::from_hash(_tag)
        }

        /// Construct a set with default hash and key equality functions.
        ///
        /// This demonstrates calling a C++ constructor with default arguments.
        /// In C++, this would be `unordered_multiset(0, std::hash<int>(), std::equal_to<int>())`
        /// where the remaining arguments use their default values.
        pub fn new(_tag: DefaultKeyEqual) -> StdUnorderedMultiset {
            StdUnorderedMultiset::from_key_equal(_tag)
        }
    }
}

overload! {
    impl StdUnorderedMultiset {
        /// Insert a single value into the set.
        pub fn insert(&mut self, value: T) {
            self.insert_value(value)
        }

        /// Insert a range of values from a slice into the set.
        ///
        /// ### Ergonomics
        ///
        /// The `as_slice()` call is required to match the slice overload, as arrays don't automatically coerce.
        pub fn insert(&mut self, items: &[T]) {
            self.insert_range(items)
        }
    }
}

#[test]
pub fn test_unordered_multiset() {
    let default_set = StdUnorderedMultiset::new();
    assert!(default_set.is_empty());

    let from_slice = StdUnorderedMultiset::new([1, 2, 3].as_slice());
    assert_eq!(from_slice.count(1), 1);

    let from_bucket_count = StdUnorderedMultiset::new(10 as c_size_t);
    assert!(from_bucket_count.is_empty());

    let from_initializer_list = StdUnorderedMultiset::new(2, 1);
    assert_eq!(from_initializer_list.count(2), 1);

    let empty_set = StdUnorderedMultiset::new();
    let copied = StdUnorderedMultiset::new(&empty_set);
    assert!(copied.is_empty());

    let from_hash = StdUnorderedMultiset::new(DefaultHash);
    assert!(from_hash.is_empty());

    let from_key_equal = StdUnorderedMultiset::new(DefaultKeyEqual);
    assert!(from_key_equal.is_empty());

    let mut insert_set = StdUnorderedMultiset::new();
    insert_set.insert(42);
    assert_eq!(insert_set.count(42), 1);

    let mut insert_set = StdUnorderedMultiset::new();
    insert_set.insert([1, 2, 3].as_slice());
    assert_eq!(insert_set.count(1), 1);
}
